model SemPk {
  id Int
  nome String?
  @@map("sem_pk")
}

model CampoDup {
  id Int @id
  nome String? @map("Nome")
  nOME String? @map("NOME")
  @@map("campo_dup")
}

model TabelaComUmNomeAbsurdamenteLongoQueUltrapassaOLimiteDoPostgres63 {
  id Int @id
  colunaComUmNomeAbsurdamenteLongoQueUltrapassaOLimiteDoPostgres63 Int? @map("coluna_com_um_nome_absurdamente_longo_que_ultrapassa_o_limite_do_postgres_63")
  @@map("tabela_com_um_nome_absurdamente_longo_que_ultrapassa_o_limite_do_postgres_63")
}

model CicloA {
  id Int @id
  bId Int? @map("b_id")
  b CicloB @relation(fields: [bId], references: [id])
  cicloBs CicloB[]
  @@map("ciclo_a")
}

model CicloB {
  id Int @id
  aId Int? @map("a_id")
  a CicloA @relation(fields: [aId], references: [id])
  cicloAs CicloA[]
  @@map("ciclo_b")
}

model CicloX {
  id Int @id
  zId Int? @map("z_id")
  z CicloZ @relation(fields: [zId], references: [id])
  cicloYs CicloY[]
  @@map("ciclo_x")
}

model CicloY {
  id Int @id
  xId Int? @map("x_id")
  x CicloX @relation(fields: [xId], references: [id])
  cicloZs CicloZ[]
  @@map("ciclo_y")
}

model CicloZ {
  id Int @id
  yId Int? @map("y_id")
  y CicloY @relation(fields: [yId], references: [id])
  cicloXs CicloX[]
  @@map("ciclo_z")
}

model Hierarquia {
  id Int @id
  paiId Int? @map("pai_id")
  pai Hierarquia @relation(fields: [paiId], references: [id])
  hierarquias Hierarquia[]
}

model PartSemChave {
  id Int @id
  dia DateTime?
  @@map("part_sem_chave")
}

model PartEstrategiaInvalida {
  id Int?
  dia DateTime?

  @@id([id, dia])
  @@map("part_estrategia_invalida")
}

model PartPkIncompleta {
  id Int @id
  dia DateTime?
  regiao String?
  @@unique([id, dia])
  @@map("part_pk_incompleta")
}

model PartOk {
  id Int?
  dia DateTime?

  @@id([id, dia])
  @@map("part_ok")
}

model PartOk2024 {
  @@map("part_ok_2024")
}

model PartOkDefault {
  @@map("part_ok_default")
}

model PartOk2025 {
  @@map("part_ok_2025")
}

model FilhaHerdada {
  @@map("filha_herdada")
}

model Espacial {
  id Int @id
  geomSemSrid String? @map("geom_sem_srid")
  geomComSubtipo String? @map("geom_com_subtipo")
  geomComSrid String? @map("geom_com_srid")
  geog String?
}

